{
  "packet_id": "H6-T01-3",
  "claim_id": "C034",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C034.component",
    "value": "Selection should favor the feasible change addressing the largest credible, avoidable delay burden without purchasing equipment or adding staff.",
    "scope": "A comparative selection rule constrained by feasibility, credibility, avoidability and existing resources; no burden-calculation formula is supplied.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P024 supplies the selection rule and its constraints. P015 identifies the selection as a narrowly scoped, reversible trial."
    }
  },
  "signal_basis": {
    "component_id": "C034.signal_basis",
    "value": "Compare candidate changes using independently corroborated failure patterns, their frequency and delay burden, feasibility and effects on other crews. Count supported patterns across bookings and check whether they also occur in timely bookings. Repeated supported sequences can support trial prioritization, while corroborated timing alone does not establish the cause of lateness.",
    "scope": "Evidence for comparative trial prioritization; corroboration establishes specific timing or status features without automatically establishing causation or intervention effectiveness.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the comparison dimensions, cross-booking checks, bounded corroboration inference and trial-prioritization rationale, including the causal limitation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C034.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the bounded selection rule is supported without asserting an unresolved empirical relation as established."
    }
  },
  "rationale": "The operation provides relevant grounds for comparing trial candidates against the stated delay-reduction objective and resource constraints. The claim expresses a qualified preference among candidates, not a finding that a particular change has the largest avoidable burden or will reduce delays. Within that scope, the observed patterns license the selection rule.",
  "uncertainty": "The mapping supplies no burden-calculation formula, and corroboration alone cannot establish how much delay a candidate would prevent. These limitations affect applying the rule to a particular candidate, without defeating the rule itself.",
  "anomalies": []
}
